import{_ as t,o,c as a,a2 as d}from"./chunks/framework.76ZGnlPi.js";const g=JSON.parse('{"title":"Storage — Download a File by its ID","description":"","frontmatter":{},"headers":[],"relativePath":"storage/index.md","filePath":"storage/index.md"}'),i={name:"storage/index.md"};function n(s,e,r,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="storage-—-download-a-file-by-its-id" tabindex="-1">Storage — Download a File by its ID <a class="header-anchor" href="#storage-—-download-a-file-by-its-id" aria-label="Permalink to &quot;Storage — Download a File by its ID&quot;">​</a></h1><p>Every file uploaded through the API (SPK, KTP, NIB, partnership document, payment proof, generated ticket, manual-transfer proof, …) is stored once and identified by a single <strong><code>File.id</code></strong>. Wherever a response gives you a document id (<code>spkDocumentId</code>, <code>ktpDocumentId</code>, <code>nibDocument.id</code>, <code>manualTransfer.fileId</code>, ticket <code>fileId</code>, …), that id is the handle you use to download the file here.</p><p>All storage routes live under the versioned prefix <strong><code>/api/v1/storage</code></strong>.</p><hr><h2 id="access-model-who-can-download-what" tabindex="-1">Access model (who can download what) <a class="header-anchor" href="#access-model-who-can-download-what" aria-label="Permalink to &quot;Access model (who can download what)&quot;">​</a></h2><p>A file has one <strong>visibility</strong>: <code>PUBLIC</code>, <code>ORGANIZATION</code>, or <code>PRIVATE</code>. Access is decided by <code>validateFileAccess</code> in <code>storage.service.ts</code>:</p><table tabindex="0"><thead><tr><th>Caller</th><th><code>PUBLIC</code> file</th><th><code>ORGANIZATION</code> file</th><th><code>PRIVATE</code> file</th></tr></thead><tbody><tr><td><strong>Admin</strong></td><td>✅</td><td>✅</td><td>✅ (any file)</td></tr><tr><td><strong>File owner</strong> (<code>file.userId === your id</code>)</td><td>✅</td><td>✅</td><td>✅ (your own)</td></tr><tr><td><strong>Same-organization member</strong></td><td>✅</td><td>✅ (same <code>organizationId</code>)</td><td>❌</td></tr><tr><td><strong>Other authenticated user</strong></td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td><strong>Anonymous (no token)</strong></td><td>✅</td><td>❌</td><td>❌</td></tr></tbody></table><p>Most sensitive documents (SPK, KTP, NIB, payment/transfer proofs) are <code>PRIVATE</code>, so only <strong>the file&#39;s owner or an admin</strong> can download them — not any logged-in user.</p><p>Owner is not always the uploader. A manual-transfer proof belongs to the <strong>invoice owner</strong> even when an admin submitted it for them, so the customer can always read their own receipt back. See <a href="/ahlaan-train-docs/customer/manual-transfer/#download-your-proof-file">Manual transfer — download your proof file</a>.</p><hr><h2 id="the-four-download-routes" tabindex="-1">The four download routes <a class="header-anchor" href="#the-four-download-routes" aria-label="Permalink to &quot;The four download routes&quot;">​</a></h2><h3 id="_1-direct-download-—-get-api-v1-storage-fileid-download" tabindex="-1">1. Direct download — <code>GET /api/v1/storage/{fileId}/download</code> <a class="header-anchor" href="#_1-direct-download-—-get-api-v1-storage-fileid-download" aria-label="Permalink to &quot;1. Direct download — `GET /api/v1/storage/{fileId}/download`&quot;">​</a></h3><p>Returns the raw bytes with <code>Content-Disposition: attachment</code>.</p><ul><li><strong>Auth:</strong> optional bearer token (<code>OptionalAuthGuard</code>). The same <code>validateFileAccess</code> check above applies: admin → any file; owner → own <code>PRIVATE</code>; org member → <code>ORGANIZATION</code> file of their org; anonymous → <code>PUBLIC</code> only.</li><li><strong>Use when:</strong> you have the <code>fileId</code> and the caller is the owner or an admin.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/storage/019f6427-1733-72dd-b0b8-04dfc67450f2/download</span></span>\n<span class="line"><span>Authorization: Bearer &lt;token&gt;</span></span></code></pre></div><h3 id="_2-presigned-url-—-get-api-v1-storage-fileid-url-expiresin-3600" tabindex="-1">2. Presigned URL — <code>GET /api/v1/storage/{fileId}/url?expiresIn=3600</code> <a class="header-anchor" href="#_2-presigned-url-—-get-api-v1-storage-fileid-url-expiresin-3600" aria-label="Permalink to &quot;2. Presigned URL — `GET /api/v1/storage/{fileId}/url?expiresIn=3600`&quot;">​</a></h3><p>Returns a time-limited direct link instead of the bytes:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;expiresIn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><ul><li><strong>Auth:</strong> bearer token <strong>required</strong>, and the <strong>same owner-or-admin <code>validateFileAccess</code> check</strong> — this is <em>not</em> &quot;any JWT holder&quot;. A user who does not own the file (and is not admin) gets <code>403</code>.</li><li><strong><code>expiresIn</code>:</strong> seconds, default <strong>3600</strong> (1 hour).</li><li><strong>Use when:</strong> the frontend needs a link the browser can open/preview directly.</li></ul><h3 id="_3-shareable-token-—-post-api-v1-storage-fileid-token-→-get-api-v1-storage-ticket-token-download" tabindex="-1">3. Shareable token — <code>POST /api/v1/storage/{fileId}/token</code> → <code>GET /api/v1/storage/ticket/{token}/download</code> <a class="header-anchor" href="#_3-shareable-token-—-post-api-v1-storage-fileid-token-→-get-api-v1-storage-ticket-token-download" aria-label="Permalink to &quot;3. Shareable token — `POST /api/v1/storage/{fileId}/token` → `GET /api/v1/storage/ticket/{token}/download`&quot;">​</a></h3><p>A two-step flow for links that must work <strong>without</strong> the recipient logging in (email links, previews):</p><ol><li><p><strong>Mint</strong> the token — bearer token required, and the <strong>same owner-or-admin <code>validateFileAccess</code> check</strong> to prove you may share this file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/storage/{fileId}/token</span></span>\n<span class="line"><span>Authorization: Bearer &lt;token&gt;</span></span>\n<span class="line"><span>{ &quot;expiresIn&quot;: 86400, &quot;maxDownloads&quot;: 1 }</span></span></code></pre></div><p><code>expiresIn</code> defaults to <strong>86400</strong> (24 h); <code>maxDownloads</code> defaults to <strong>1</strong>.</p></li><li><p><strong>Redeem</strong> the token — <strong>no auth</strong>; the token itself is the capability:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/storage/ticket/{token}/download</span></span></code></pre></div><p>The token is rejected once it is expired or its download count reaches <code>maxDownloads</code>.</p></li></ol><ul><li><strong>Use when:</strong> a guest / email recipient must download a <code>PRIVATE</code> file they do not own.</li></ul><h3 id="_4-public-file-—-get-api-v1-storage-public-fileid" tabindex="-1">4. Public file — <code>GET /api/v1/storage/public/{fileId}</code> <a class="header-anchor" href="#_4-public-file-—-get-api-v1-storage-public-fileid" aria-label="Permalink to &quot;4. Public file — `GET /api/v1/storage/public/{fileId}`&quot;">​</a></h3><p>No authentication, but serves <strong><code>PUBLIC</code>-visibility files only</strong>. It will <strong>not</strong> return <code>PRIVATE</code> documents (SPK/KTP/NIB/proofs) even with a valid id — use route 1 (as owner/admin) or route 3 (a minted token) for those.</p><hr><h2 id="choosing-a-route" tabindex="-1">Choosing a route <a class="header-anchor" href="#choosing-a-route" aria-label="Permalink to &quot;Choosing a route&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You need…</th><th>Use</th></tr></thead><tbody><tr><td>Owner/admin downloads their own document</td><td>Route 1 (<code>/download</code>)</td></tr><tr><td>A browser-openable link, still access-checked</td><td>Route 2 (<code>/url</code>)</td></tr><tr><td>A link that works for a not-logged-in recipient</td><td>Route 3 (<code>/token</code> → <code>/ticket</code>)</td></tr><tr><td>A genuinely public asset</td><td>Route 4 (<code>/public</code>)</td></tr></tbody></table>',28)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
